local _, ns = ...
if ns.LOCALE ~= "esES" and ns.LOCALE ~= "esMX" then return end
local L = ns.L

-- Options/Welcome.lua: What's New, by version (WN<id>_<n>), newest first; beside Locales/esES.lua.
L["WN99_1_TITLE"] = "Compartir misiones"
L["WN99_1_TEXT"] = "Compartir misiones desde el registro de misiones vuelve a funcionar con tu grupo."
L["WN99_2_TITLE"] = "Menús desplegables de Opciones"
L["WN99_2_TEXT"] = "Los menús desplegables de las Opciones del juego ya no muestran un botón estirado dentro con un tema personalizado texturizado."
L["WN99_3_TITLE"] = "En combate"
L["WN99_3_TEXT"] = "En combate, las barras de acción ya no saltan cuando se abre una ventana con un botón del micromenú oculto, el libro de profesiones abierto desde el libro de hechizos se queda en su sitio sin un segundo panel vacío, e inspeccionar los talentos de un jugador desde su menú abre solo nuestra ventana, sin errores."
L["WN99_4_TITLE"] = "Chat"
L["WN99_4_TEXT"] = "El chat y sus pestañas ya no desaparecen cuando otro addon cambia el tamaño del chat."
L["WN99_5_TITLE"] = "Desplegables y What's Training"
L["WN99_5_TEXT"] = "Con un tema propio texturizado, los desplegables de nuestras opciones vuelven a dibujarse enteros, y What's Training en el libro de profesiones lleva el mármol negro del libro de hechizos sin líneas sobre la lista."
L["WN98_1_TITLE"] = "Iconos de bolsa en ranuras vacías"
L["WN98_1_TEXT"] = "En Una bolsa, cada ranura vacía muestra ahora un icono atenuado de la bolsa a la que pertenece, así las ranuras de un carcaj se ven al instante. Actívala en las opciones (/fcui): Una bolsa, en Bolsas. Ranuras vacías lisas, justo debajo, las vuelve a dejar todas iguales."
L["WN98_2_TITLE"] = "Colores de clase en campos de batalla"
L["WN98_2_TEXT"] = "Las placas de nombre de los jugadores enemigos ahora muestran su color de clase en campos de batalla y mazmorras, donde el juego oculta su clase y se veían en rojo."
L["WN98_3_TITLE"] = "Las bolsas se quedan en su sitio"
L["WN98_3_TEXT"] = "Las bolsas que mueves en el modo de edición ahora se quedan donde las dejas. Las que colocaste antes de esta versión siguen donde están."
L["WN98_4_TITLE"] = "Ventanas por encima"
L["WN98_4_TEXT"] = "Una ventana que arrastras sobre el registro de misiones o el libro de hechizos ahora queda encima, y los iconos del libro de hechizos ya no se transparentan."
L["WN98_5_TITLE"] = "Pestañas del buscador de grupos"
L["WN98_5_TEXT"] = "El buscador de grupos y una ventana que otro addon abre desde sus pestañas laterales ahora comparten un mismo sitio, así que cambiar de pestaña ya no salta, y arrastrar cualquiera de las dos mueve ambas."
L["WN97_1_TITLE"] = "Sin hueco al nivel máximo"
L["WN97_1_TEXT"] = "Al nivel máximo, sin barra de experiencia ni de reputación, las barras sobre la barra principal ahora se apoyan en la barra fina donde estaba la experiencia, como en Era."
L["WN97_2_TITLE"] = "Desafíos de Legado"
L["WN97_2_TEXT"] = "La lista de Desafíos anida sus secciones como la ventana del juego, y su búsqueda encuentra cualquier palabra que muestre un desafío, desde sus secciones hasta sus pasos."
L["WN97_3_TITLE"] = "Pestañas laterales de otros addons"
L["WN97_3_TEXT"] = "Las pestañas laterales que otros addons añaden al buscador de grupos, como la de LFG Forever, ahora se ven como las nuestras y se colocan debajo de ellas."
L["WN96_1_TITLE"] = "Tiradas de botín de Era"
L["WN96_1_TEXT"] = "/loot abre la ventana de tiradas de botín de Era: cada objeto con su ganador y su tirada, y + en un objeto muestra todas las tiradas. Arrastra la pestaña de debajo para la altura, o su esquina para ambos sentidos."
L["WN96_2_TITLE"] = "Aparecer desconectado"
L["WN96_2_TEXT"] = "El menú de estado de la ventana social clásica ahora incluye aparecer desconectado, junto a Disponible, Ausente y Ocupado."
L["WN96_3_TITLE"] = "Social desmarcado"
L["WN96_3_TEXT"] = "Al desmarcar Social en la página Todas las ventanas ahora tienes la ventana social del juego, sin ninguna de nuestras pestañas."
L["WN95_1_TITLE"] = "Una bolsa por perfil"
L["WN95_1_TEXT"] = "Los perfiles ahora guardan la opción Una bolsa, así que los personajes con perfiles distintos conservan su propio modo de bolsas. Antes, un cambio en un personaje se aplicaba a todos. Actívala en las opciones (/fcui) en cada perfil que la quiera: Una bolsa, en Bolsas."
L["WN95_2_TITLE"] = "Estadísticas en combate"
L["WN95_2_TEXT"] = "Las estadísticas de la ventana de personaje ya no aparecen vacías al abrirla por primera vez en combate, y los atributos, la salud, la armadura, el crítico, la celeridad y el esquivar siguen a los beneficios durante el combate."
L["WN94_1_TITLE"] = "Repartir botín"
L["WN94_1_TEXT"] = "Repartir el botín al grupo vuelve a funcionar con la ventana de botín clásica: al hacer clic en un objeto aparece la lista de jugadores, al estilo de Era debajo del objeto."
L["WN93_1_TITLE"] = "Estilos de placas de nombre"
L["WN93_1_TEXT"] = "Clásico está ahora en la lista de estilos de placas de nombre del juego (Opciones, Placas de nombre). Elegir uno de los estilos del juego desactiva nuestras placas para que se vea ese estilo; Clásico trae las nuestras de vuelta."
L["WN93_2_TITLE"] = "Historial de botín"
L["WN93_2_TEXT"] = "La ventana del historial de botín (/loot) lleva el marco clásico con tu tema. Arrastra su esquina para cambiar su tamaño en ambos sentidos; clic derecho en la esquina para su propio tamaño."
L["WN93_3_TITLE"] = "Fondo de la barra de actitud"
L["WN93_3_TEXT"] = "El fondo tras las barras de actitud y de mascota sigue el tema de las barras de acción, como el arte de la propia barra."
L["WN93_4_TITLE"] = "Cantidad en profesiones"
L["WN93_4_TEXT"] = "Hacer clic en la casilla de cantidad de la ventana clásica de profesiones selecciona el número, así que al escribir lo reemplazas, como en Era."
L["WN92_1_TITLE"] = "Barras de actitud y de mascota"
L["WN92_1_TEXT"] = "Las barras de actitud, de mascota y de posesión se colocan donde las pone Era: encima de la barra principal sobre el fondo propio de Era, o justo encima de la barra 2 cuando está activa. Arrastra una en el modo edición para colocarla tú."
L["WN92_2_TITLE"] = "Barra de tótems"
L["WN92_2_TEXT"] = "La barra de tótems del chamán se coloca en el sitio de la barra de actitud, encima de la barra principal, y se queda ahí tras cada carga."
L["WN92_3_TITLE"] = "Barras de acción"
L["WN92_3_TEXT"] = "Al desactivar la barra 2 o la barra 3, la otra se queda donde estaba."
L["WN92_4_TITLE"] = "Macros de profesión"
L["WN92_4_TEXT"] = "Una macro puede pulsar Crear en la ventana clásica de profesiones, como una macro de encantamiento rápido: /run ClassicUIForeverTradeSkill.CreateButton:Click()"
L["WN91_1_TITLE"] = "Seguimiento de misiones"
L["WN91_1_TEXT"] = "¿Las misiones que dejaste de seguir vuelven al seguimiento? Es el seguimiento automático de misiones del juego. Desmarca Seguimiento automático de misiones en Misiones (/fcui) y no volverán."
L["WN91_2_TITLE"] = "Panel de banda"
L["WN91_2_TEXT"] = "El panel de grupo del borde izquierdo de la pantalla puede quedar oculto hasta que pases el ratón por encima. Actívalo en las opciones (/fcui): Panel de banda al pasar el ratón, en Marcos de unidad."
L["WN90_1_TITLE"] = "Colores de misión"
L["WN90_1_TEXT"] = "¿Todas tus misiones en amarillo? Es el ajuste del juego de colores de dificultad de misión, desactivado. Ahora también está en las opciones (/fcui): marca Colores de dificultad de misión en Misiones."
L["WN90_2_TITLE"] = "Pestaña de mascota"
L["WN90_2_TEXT"] = "Muestra las estadísticas que tienen de verdad las mascotas: salud, velocidad, probabilidad de crítico, celeridad, poder de ataque, daño, defensa y armadura."
L["WN90_3_TITLE"] = "Bolsas"
L["WN90_3_TEXT"] = "Las bolsas que sueltas en la barra clásica en el modo de edición se quedan ahí al volver a conectarte, y se acabó un error de Lua que algunos addons causaban al refrescar las bolsas."
L["WN90_4_TITLE"] = "Colecciones"
L["WN90_4_TEXT"] = "En Apariencias, la vista previa encaja a todo tu personaje, y probar otra apariencia en la misma ranura deja la cámara donde la dejaste."
L["WN90_5_TITLE"] = "Registro de misiones"
L["WN90_5_TEXT"] = "Ya no se ralentiza mientras otro addon carga datos de objetos."
L["WN89_1_TITLE"] = "Sin recuadro de logros"
L["WN89_1_TEXT"] = "El recuadro del juego que aparece al completar un logro (en Forever, un desafío de Legado) o uno de sus pasos ha desaparecido, pues 1.x no tenía ninguno. Para recuperarlo, actívalo en las opciones (/fcui): marca Aviso de logro en Otros."
L["WN89_2_TITLE"] = "Pestaña Habilidades"
L["WN89_2_TEXT"] = "Su panel inferior ya no se queda a la vista cuando la ventana de personaje se abre en otra pestaña."
L["WN88_1_TITLE"] = "Mascotas"
L["WN88_1_TEXT"] = "Invocar otra mascota ya no congela el juego por un momento."
L["WN88_2_TITLE"] = "Registro de misiones"
L["WN88_2_TEXT"] = "Abandonar una misión reproduce su sonido solo cuando eliges Sí."
L["WN88_3_TITLE"] = "Profesiones"
L["WN88_3_TEXT"] = "El libro de profesiones incluye el equipo, como una caña de pescar, en la bonificación de cada habilidad."
L["WN87_1_TITLE"] = "Descripciones de unidad"
L["WN87_1_TEXT"] = "La línea que indica hacer clic derecho para las opciones del marco ya no aparece en las descripciones de los marcos de unidad, como en Era. Para verla de nuevo, desactiva Ocultar el aviso de clic derecho en las opciones (/fcui), en Marcos de unidad."
L["WN87_2_TITLE"] = "Bolsas"
L["WN87_2_TEXT"] = "La mochila conserva su imagen clásica cuando cambian las bolsas."
L["WN87_3_TITLE"] = "Ventana de personaje"
L["WN87_3_TEXT"] = "Las filas de probabilidad de golpe vuelven a mostrar su descripción."
L["WN87_4_TITLE"] = "Vendedores"
L["WN87_4_TEXT"] = "Los botones de reparar muestran los iconos de Era."
L["WN87_5_TITLE"] = "Barra de experiencia"
L["WN87_5_TEXT"] = "La barra de experiencia está donde en Era y es igual de alta."
L["WN86_1_TITLE"] = "Addons de barras de acción"
L["WN86_1_TEXT"] = "Con un addon de barras de acción que sustituye las barras del juego, sus barras conservan sus botones y su aspecto, incluidos los aspectos de Masque, y Desconectar y Salir del juego del menú del juego vuelven a funcionar."
L["WN86_2_TITLE"] = "Barra clásica desactivada"
L["WN86_2_TEXT"] = "Los botones de mascota y de actitud y el botón del personaje recuperan su propio aspecto."
L["WN85_1_TITLE"] = "Ventana de opciones del juego"
L["WN85_1_TEXT"] = "La ventana de opciones del juego ya no baja la tasa de fotogramas mientras está abierta."
L["WN85_2_TITLE"] = "Talentos"
L["WN85_2_TEXT"] = "Un talento bloqueado hasta que su árbol tenga puntos suficientes indica en rojo cuántos necesita, como en Era."
L["WN85_3_TITLE"] = "Barra de experiencia"
L["WN85_3_TEXT"] = "Las líneas de segmento del juego ya no aparecen sobre la barra de experiencia al conectarte en combate."
L["WN85_4_TITLE"] = "Profesiones"
L["WN85_4_TEXT"] = "El libro de profesiones mantiene juntos los hechizos de cada profesión cuando se abre en combate, y con TradeSkillMaster la ventana de profesiones ya no salta a la derecha al terminar un combate."
L["WN84_1_TITLE"] = "Ventanas de vendedor e instructor"
L["WN84_1_TEXT"] = "Las ventanas de vendedores e instructores ya se pueden mover y cambiar de tamaño. Haz clic en el candado junto al botón de cerrar y arrastra la ventana o su esquina. Comparten un mismo lugar y tamaño con las ventanas de misiones y de diálogo, y en Ventanas de ClassicUI Forever las ventanas que comparten lugar son una sola fila y un solo recuadro."
L["WN84_2_TITLE"] = "Seguimiento y ajustes de misiones del mapa"
L["WN84_2_TEXT"] = "Los títulos de las misiones en el seguimiento clásico, el registro de misiones y las listas de misiones del mapa siguen el ajuste del mapa Color de dificultad de misión (lisos si está desactivado), y ese ajuste y Mostrar niveles de misión se aplican al instante, sin recargar."
L["WN84_3_TITLE"] = "Correcciones"
L["WN84_3_TEXT"] = "El título de una misión en el seguimiento clásico conserva su color cuando el ratón lo deja, las barras de desplazamiento del mapa clásico combinado encajan en su sitio con el mapa en ventana, la tecla del mapa cierra ese mapa en todos los personajes, y el botón del minimapa se queda en la bolsa de MinimapButtonBag Reborn."
L["WN84_4_TITLE"] = "Pestaña Habilidades"
L["WN84_4_TEXT"] = "Que una habilidad suba en combate ya no causa un error mientras la pestaña Habilidades muestra una habilidad de arma."
L["WN83_1_TITLE"] = "Habilidades y casa de subastas"
L["WN83_1_TEXT"] = "La pestaña Habilidades ya no causa un error en personajes con una bonificación a Defensa, y el botón de puja de la casa de subastas ya no tapa el final de la casilla de cobre."
L["WN83_2_TITLE"] = "Panel de banda y mando"
L["WN83_2_TEXT"] = "La pestaña cerrada del panel de banda queda en el borde de la pantalla cuando te unes a un grupo en combate, y las opciones de mando muestran los iconos Vista y Menú de tu mando."
L["WN82_1_TITLE"] = "Compartir misión con el mapa a pantalla completa"
L["WN82_1_TEXT"] = "Compartir una misión desde el registro de misiones ya no deja abierto el mapa del mundo cuando usas el mapa a pantalla completa."
L["WN82_2_TITLE"] = "Compartir misión"
L["WN82_2_TEXT"] = "Compartir misión en el registro de misiones comparte la misión, en lugar de decir que la compartas desde el mapa del mundo."
L["WN81_1_TITLE"] = "Coste de fabricación y beneficio"
L["WN81_1_TEXT"] = "Con Auctionator, la ventana clásica de profesiones muestra sobre los componentes lo que cuesta fabricar una receta y su beneficio, y un botón Buscar para los componentes mientras la casa de subastas está abierta."
L["WN81_2_TITLE"] = "Colores de clase para amigos o enemigos"
L["WN81_2_TEXT"] = "Jugadores amistosos y Jugadores enemigos son casillas separadas en los colores de clase de las placas, el cuadro de nombre con color de clase y la salud con color de clase, así que pueden ser solo para un bando. Las opciones de color de clase están desactivadas por defecto: actívalas en las opciones (/fcui)."
L["WN81_3_TITLE"] = "Carrera automática con mando"
L["WN81_3_TEXT"] = "En el diseño clásico, la carrera automática está por defecto en la pulsación del stick izquierdo, y un botón elegido para carrera automática o chat funciona también en un stick con el que el cursor hace clic."
L["WN81_4_TITLE"] = "Correcciones"
L["WN81_4_TEXT"] = "La lista de What's Training en la ventana de profesiones de doble panel descansa sobre un solo fondo, y las barras de salud y enfoque del marco de la mascota llenan sus huecos."
L["WN80_1_TITLE"] = "Mando en el diseño clásico (en desarrollo)"
L["WN80_1_TEXT"] = "Juega con las barras clásicas usando un mando mientras la interfaz de mando del juego está desactivada: la cruceta y los botones frontales activan la barra de acción 1, o las otras barras con un gatillo pulsado. Desactivado por defecto; la primera vez que usas un mando un cuadro te lo pregunta, y está en las opciones (/fcui), en Mando. Aún en desarrollo: las bolsas, el mapa y los menús necesitan por ahora el cursor del juego."
L["WN80_2_TITLE"] = "Panel de banda en combate"
L["WN80_2_TEXT"] = "El panel de banda y grupo mantiene sus filas en su sitio cuando el grupo cambia durante un combate, y su pestaña ya no desaparece al cerrar el panel en combate."
L["WN80_3_TITLE"] = "Entrenamiento de mascotas"
L["WN80_3_TEXT"] = "La ventana del instructor ya no conserva una lista antigua, así que las habilidades que tu mascota ya conoce no quedan como disponibles para aprender."
L["WN79_1_TITLE"] = "Panel de banda en combate"
L["WN79_1_TEXT"] = "El panel de banda y grupo ya no causa un error cuando tu grupo cambia durante un combate, por ejemplo cuando un miembro del grupo sube de nivel. Se pone al día al terminar el combate."
L["WN78_1_TITLE"] = "Panel de banda clásico"
L["WN78_1_TEXT"] = "El panel de banda y grupo del borde izquierdo de la pantalla tiene el aspecto y el orden clásicos, y todos los controles del juego siguen en él. Su botón de marcadores de mundo hace que los iconos de objetivo marquen el suelo."
L["WN78_2_TITLE"] = "Borde del panel de banda"
L["WN78_2_TEXT"] = "Cerrado, el panel solo muestra su pestaña con la flecha. Borde del panel de banda al cerrarlo deja su marco en el borde de la pantalla, como en Era. Desactivado por defecto; actívalo en las opciones (/fcui), en Marcos de unidad."
L["WN78_3_TITLE"] = "Pequeñas correcciones"
L["WN78_3_TEXT"] = "La ventana de botín se abre al instante y ya no salta al hacer clic en un objeto con las bolsas llenas. Los botones de la pestaña de hermandad y de la ventana de Comunidades ya no siguen activos tras cerrarse su ventana en combate."
L["WN77_1_TITLE"] = "Búsqueda en el instructor"
L["WN77_1_TEXT"] = "La ventana de un instructor tiene un cuadro de búsqueda junto a su filtro. Solo muestra los hechizos y recetas cuyo nombre contiene las palabras. Cuadro de búsqueda, en Ventana de instructor en las opciones (/fcui), lo desactiva."
L["WN77_2_TITLE"] = "What's Training en su propia ventana"
L["WN77_2_TEXT"] = "La pestaña de entrenamiento del libro de hechizos puede abrir la ventana propia de What's Training en lugar de una página del libro; la ventana se cierra con el libro. Desactivado por defecto; actívalo en las opciones (/fcui), en Libro de hechizos."
L["WN77_3_TITLE"] = "Nombres de hermandad en color de clase"
L["WN77_3_TEXT"] = "Los nombres de la lista de la hermandad pueden mostrarse en su color de clase. Desactivado por defecto; actívalo en las opciones (/fcui), en Lista de la hermandad."
L["WN77_4_TITLE"] = "Banco clásico"
L["WN77_4_TEXT"] = "El banco tiene las placas de casilla y los remaches clásicos, con su espaciado clásico, en una ventana más corta."
L["WN77_5_TITLE"] = "Cuadros de búsqueda"
L["WN77_5_TEXT"] = "Los cuadros de búsqueda del registro de misiones y de las profesiones tienen el aspecto de entrada clásico."
L["WN77_6_TITLE"] = "Avisos sobre el chat"
L["WN77_6_TEXT"] = "Los avisos de amigos y el aviso de actualización del mundo se colocan sobre las pestañas del chat. En un chat más alto tapaban su texto y sus pestañas."
L["WN77_7_TITLE"] = "Pequeñas correcciones"
L["WN77_7_TEXT"] = "Forever Quest Tint cubre toda la página de misión del mapa, no una franja bajo el título. Cerrar un banco o un vendedor ya no aparta un instante las bolsas abiertas, y /fstack ya no lista los marcos auxiliares ocultos del addon."
L["WN76_1_TITLE"] = "Búsqueda en el registro de misiones"
L["WN76_1_TEXT"] = "El registro de misiones de panel doble tiene un cuadro de búsqueda en su cabecera. Muestra las misiones cuyo nombre o zona contiene las palabras."
L["WN76_2_TITLE"] = "Ordenar por dificultad"
L["WN76_2_TEXT"] = "Todas las recetas de una profesión en una sola lista, primero naranja, luego amarillo, verde y gris. Actívalo en el menú Filtro de la ventana de una profesión o en las opciones (/fcui), en Profesiones."
L["WN76_3_TITLE"] = "Botones de cierre clásicos"
L["WN76_3_TEXT"] = "El banco de hermandad y el mapa del maestro de vuelo tienen la X clásica."
L["WN75_1_TITLE"] = "Descripción de un enlace de objeto"
L["WN75_1_TEXT"] = "La X de la descripción de un enlace de objeto es la clásica, en su sitio clásico."
L["WN75_2_TITLE"] = "Habilidades de mascota en el cursor"
L["WN75_2_TEXT"] = "Tras cambiar de mascota, una habilidad de mascota cuya copia el juego no conserva se coloca una vez, no una y otra vez. Con algunas mascotas eso dejaba iconos en el cursor y frenaba el juego."
L["WN74_1_TITLE"] = "Página de entrenamiento del libro de hechizos"
L["WN74_1_TEXT"] = "La página de entrenamiento del libro de hechizos funciona con What's Training 11.3. Con esa versión la pestaña abría la propia ventana de What's Training en vez de la lista en el libro."
L["WN74_2_TITLE"] = "Compartir misión desde el registro"
L["WN74_2_TEXT"] = "Compartir misión en el registro de misiones también comparte misiones fuera de la zona en la que estás, mazmorras incluidas, y deja el mapa del mundo cerrado después."
L["WN73_1_TITLE"] = "Entrenamiento en la ventana de una profesión"
L["WN73_1_TEXT"] = "Con What's Training instalado, la ventana de una profesión tiene dos pestañas laterales: la de abajo lista lo que su instructor puede enseñarte, la de arriba vuelve a la profesión. Las pestañas de entrenamiento llevan los iconos propios de What's Training, también en el libro de hechizos."
L["WN73_2_TITLE"] = "Saquear en combate"
L["WN73_2_TEXT"] = "Saquear un cadáver en combate abre la ventana de botín. Desde el segundo saqueo de una sesión, el juego lo rechazaba con el mensaje de que una acción de la interfaz falló por un addon."
L["WN73_3_TITLE"] = "Libro de hechizos"
L["WN73_3_TEXT"] = "El botón del micromenú y la tecla cierran el libro desde la página de What's Training, y un libro cerrado allí vuelve a abrirse. En combate el libro se abre al inicio de la fila de ventanas; se abría muy a la derecha cuando el mapa estaba abierto al empezar el combate."
L["WN73_4_TITLE"] = "Tamaño de placas por personaje"
L["WN73_4_TEXT"] = "Mismo tamaño cerca y lejos aplica la elección de cada personaje al conectarse. Solo surtía efecto tras cambiar la casilla en ese personaje. Actívalo en las opciones (/fcui), en Placas de nombre."
L["WN72_1_TITLE"] = "Probador"
L["WN72_1_TEXT"] = "El probador se abre al tamaño de 1.x. Para el probador más grande de los clientes posteriores, activa Probador grande en las opciones (/fcui), en Todas las ventanas; nuestras ventanas le dejan sitio al lado para sus paneles laterales."
L["WN72_2_TITLE"] = "Atenuar el micromenú"
L["WN72_2_TEXT"] = "El micromenú puede atenuarse como las barras de acción: ajusta Opacidad atenuada o Mostrar solo al pasar el ratón en su diálogo del modo de edición, y enlázalo con las barras atenuadas."
L["WN72_3_TITLE"] = "Ventana de hermandad"
L["WN72_3_TEXT"] = "Añadir miembro, Información de hermandad y el menú de clic derecho de un miembro pasan por los botones y el menú propios del juego, así que invitar, editar la información, expulsar, ascender y degradar funcionan."
L["WN72_4_TITLE"] = "Pestaña lateral Quién"
L["WN72_4_TEXT"] = "La pestaña lateral Quién del buscador de grupos está oculta para todos. Desactiva Ocultar pestaña lateral Quién en las opciones (/fcui), en Social, para recuperarla."
L["WN72_5_TITLE"] = "Tamaño de las placas de nombre"
L["WN72_5_TEXT"] = "Mismo tamaño cerca y lejos mantiene las placas a un solo tamaño como en Classic Era, ahora mediante los ajustes propios del juego y guardado por personaje, fuera de los perfiles. Actívalo en las opciones (/fcui), en Placas de nombre."
L["WN72_6_TITLE"] = "Correcciones"
L["WN72_6_TEXT"] = "Un nombre largo de hermandad termina en puntos antes de la columna de zona, la ventana del instructor desplaza una descripción larga, Ctrl+clic en una recompensa de misión abre el probador, los botones de la barra de tótems llevan el aspecto clásico, el número de grupo de una misión se mantiene con los niveles de misión desactivados, y las listas de What's Training están en una página del libro de hechizos con una pestaña Profesiones al lado."
L["WN71_1_TITLE"] = "La barra de tótems se queda en su sitio"
L["WN71_1_TEXT"] = "Una barra ajustada a una barra de acción en el modo de edición, como la barra de tótems del chamán, conserva su sitio al cerrar el modo de edición y tras recargar."
L["WN71_2_TITLE"] = "Bandejas de botones del minimapa"
L["WN71_2_TEXT"] = "Una bandeja de botones del minimapa de otro addon vuelve a poder moverse con ClassicUI Forever activo."
L["WN71_3_TITLE"] = "Porcentaje de amenaza"
L["WN71_3_TEXT"] = "El porcentaje de amenaza sobre el objetivo y el foco se detiene en 999 %, como en Classic Era."
L["WN70_1_TITLE"] = "Atenuado enlazado"
L["WN70_1_TEXT"] = "Las barras de acción atenuadas pueden volver juntas: marca Enlazada con otras barras atenuadas en las barras atenuadas, en el modo de edición, y el ratón sobre cualquiera de ellas las muestra todas (#255)."
L["WN70_2_TITLE"] = "Brillo al encantar"
L["WN70_2_TEXT"] = "El brillo dorado del juego tras una piedra de afilar, un aceite o un encantamiento está desactivado, pues Classic Era no lo tenía. Para recuperarlo, actívalo en las opciones (/fcui): Brillo dorado al encantar en Ficha de personaje. Ahora recorre el borde de la ventana (#262)."
L["WN70_4_TITLE"] = "Pestaña de títulos"
L["WN70_4_TEXT"] = "El panel lateral de la ventana de personaje vuelve a tener la pestaña Títulos (#261). Los iconos de talentos llenan sus casillas como en Classic Era (#260)."
L["WN70_3_TITLE"] = "Ventana de botín con el mando"
L["WN70_3_TEXT"] = "Con el mando, la cruceta recorre los objetos de la ventana de botín (#264)."
L["WN69_1_TITLE"] = "Nuestras ventanas con el mando"
L["WN69_1_TEXT"] = "Con la interfaz de mando activa, el libro de hechizos clásico, los talentos, el registro de misiones, las colecciones, la ventana Legacy y la bolsa única funcionan con el mando: la cruceta mueve, A selecciona, B cierra, y los botones que pulsar se ven bajo la ventana. El libro de hechizos y los talentos vuelven a abrirse como ventanas propias. En el registro de misiones la lista se desplaza al avanzar, y Y abre el mapa."
L["WN69_2_TITLE"] = "Asignar hechizos desde el libro de hechizos"
L["WN69_2_TEXT"] = "Con el mando, pulsa X sobre un hechizo del libro de hechizos clásico y luego el botón para él; mantén LT o RT para los grupos laterales, como en el libro del propio juego. Y abre el editor de barras de acción del juego."
L["WN69_3_TITLE"] = "Pestañas de profesión ocultas"
L["WN69_3_TEXT"] = "Las pestañas junto a la ventana de profesiones están ocultas, pues Classic Era no las tenía. Para recuperarlas, actívalas en las opciones (/fcui): elige Pestañas de profesión: al pasar el ratón o siempre visibles en Libro de profesiones. La lista de recetas por aprender de What's Training se abre desde una pestaña junto al libro (#260)."
L["WN69_4_TITLE"] = "Cambios menores"
L["WN69_4_TEXT"] = "La ventana de chat conserva su sitio cuando otro accesorio la redimensiona por su borde superior (#247). Con el mando, las pestañas Libro de hechizos y Colecciones de la ventana de profesiones pasan la página en su sitio, y el contorno de la ventana del personaje se ajusta a su marco."
L["WN68_1_TITLE"] = "Pestañas de doble especialización en la ventana de talentos"
L["WN68_1_TEXT"] = "Las pestañas de las dos especializaciones bajan por el borde de la ventana de talentos, como en Classic. Haz clic en una para ver esa especialización."
L["WN68_2_TITLE"] = "El texto del mapa del mundo a tamaño del juego"
L["WN68_2_TEXT"] = "En el estilo Classic de la cabecera, la cabecera, el panel de misiones y Opciones del mapa se veían al 70 % del tamaño del texto del juego en ventana. Ahora tienen el tamaño del juego, el panel de misiones tiene su anchura completa, y las etiquetas Continente y Zona van junto a sus desplegables."
L["WN68_3_TITLE"] = "Misiones sobre pergamino en el panel del mapa"
L["WN68_3_TEXT"] = "El panel de misiones del mapa lista las misiones sobre el pergamino del juego. Para la piedra oscura, desmarca Lista sobre el pergamino del juego en Mapa del mundo."
L["WN68_4_TITLE"] = "Botones de accesorios que se quedan en el anillo"
L["WN68_4_TEXT"] = "Con Agrupar botones de accesorios activado, Dejar en el anillo lista cada botón de accesorio; marca los que se quedan en el anillo mientras los demás van a la bolsa. Agrupar botones de accesorios está desactivado por defecto; actívalo en las opciones (/fcui), en Minimapa."
L["WN68_5_TITLE"] = "Sin recuadro de Nueva receta aprendida"
L["WN68_5_TEXT"] = "El recuadro del juego que aparece cuando una profesión te enseña algo ha desaparecido, pues 1.x no tenía ninguno. Para recuperarlo, actívalo en las opciones (/fcui): marca Aviso de habilidad en Otros."
L["WN68_6_TITLE"] = "Cambios menores"
L["WN68_6_TEXT"] = "Un talento por debajo de su rango máximo es verde tengas o no puntos que gastar, como en Classic Era. Las listas de la ventana social cuentan sus filas enteras (#232), y la fila Números de daño ha desaparecido, pues solo reflejaba el ajuste del propio juego."
L["WN67_1_TITLE"] = "Las piezas del minimapa se quedan en él"
L["WN67_1_TEXT"] = "Cada pieza del minimapa en ClassicUI Forever Windows tiene una casilla Quedarse en el minimapa. Marcada, la pieza conserva su sitio en el minimapa. Desmárcala para arrastrarla a cualquier parte."
L["WN67_2_TITLE"] = "La ventana de Opciones sigue el tema"
L["WN67_2_TEXT"] = "Su borde y las piezas de Classic Era llevan el aspecto oscuro, bronce o personalizado, y en el aspecto clásico no queda bronce en sus bordes."
L["WN67_3_TITLE"] = "Los huecos y la cabecera de la bolsa única"
L["WN67_3_TEXT"] = "Los huecos vacíos no muestran icono de bolsa, la búsqueda llega hasta el botón Limpiar y la banda de cabecera está completa."
L["WN67_4_TITLE"] = "El mapa del mundo en combate"
L["WN67_4_TEXT"] = "Abierto en combate, el mapa lo dimensiona solo el addon, así que otro addon de mapa ya no puede provocar un error de acción bloqueada."
L["WN66_1_TITLE"] = "Las descripciones vuelven a ser oscuras como en Classic Era"
L["WN66_1_TEXT"] = "Cada descripción lleva el fondo oscuro de Era en todos los estilos. El fondo más claro y azulado del juego se veía a partir de la segunda descripción, con un hueco dentro del borde."
L["WN66_2_TITLE"] = "El minimapa vuelve a moverse en el modo de edición"
L["WN66_2_TEXT"] = "Al arrastrar el minimapa en el modo de edición sigue a la vista y se guarda su nuevo sitio."
L["WN66_3_TITLE"] = "El mapa del mundo mantiene su tamaño en combate"
L["WN66_3_TEXT"] = "Abierto en combate, el mapa tiene el mismo tamaño que fuera de él, con o sin el registro de misiones."
L["WN65_1_TITLE"] = "Mueve todas tus ventanas a la vez"
L["WN65_1_TEXT"] = "ClassicUI Forever Windows tiene un recuadro Fila de ventanas: arrástralo y todas las ventanas que se abren una al lado de otra se mueven juntas allí."
L["WN65_2_TITLE"] = "El adiestramiento vuelve a contar en puntos de entrenamiento"
L["WN65_2_TEXT"] = "La ventana del adiestrador muestra los puntos de entrenamiento de tu mascota y lo que cuesta cada habilidad en puntos, y Entrenar se guía por ellos, como en Classic Era."

L["WN64_1_TITLE"] = "Atenúa tus barras de acción"
L["WN64_1_TEXT"] = "Elige una barra en el modo de edición: bajo los ajustes del juego para ella, fija hasta dónde se atenúa o marca Mostrar solo al pasar el ratón. Vuelve a verse entera con el ratón encima o al arrastrar un hechizo a ella."
L["WN64_2_TITLE"] = "Error de las placas de nombre corregido"
L["WN64_2_TEXT"] = "Con las placas de nombre del juego y las auras de otro addon en ellas, las placas nuevas ya no causan un error de Lua."
L["WN64_3_TITLE"] = "Huecos vacíos tras el libro de hechizos"
L["WN64_3_TEXT"] = "Con Mostrar siempre los botones desactivado, los huecos vacíos de tus barras vuelven a verse para un hechizo u objeto que cojas tras cerrar el libro de hechizos."
L["WN64_4_TITLE"] = "Correcciones en ClassicUI Forever Windows"
L["WN64_4_TEXT"] = "Su casilla en el modo de edición vuelve a responder a los clics, y el tamaño del mapa del mundo ahí cambia de forma uniforme desde el tamaño con que se abre."

L["WN63_1_TITLE"] = "Descripciones del botín junto al objeto"
L["WN63_1_TEXT"] = "En la ventana de botín, la descripción de un objeto se abre junto a su icono, como en Classic Era, y no más allá del borde derecho de la ventana."

L["WN62_1_TITLE"] = "Separa tus barras de acción"
L["WN62_1_TEXT"] = "El espaciado de iconos del modo de edición ahora separa los botones de cada barra de acción. En la barra de acción 1 la franja de piedra se ensancha con él y cada botón sigue en su hueco."
L["WN62_2_TITLE"] = "Desenvuelve regalos en Colecciones"
L["WN62_2_TEXT"] = "Las monturas, mascotas y juguetes envueltos para regalo se pueden desenvolver en la ventana clásica de Colecciones: elige uno y pulsa Desenvolver, o haz clic en un juguete envuelto."
L["WN62_3_TITLE"] = "Descripciones como en Classic Era"
L["WN62_3_TEXT"] = "Las descripciones emergentes del aspecto clásico tienen el fondo de Classic Era: el mismo color oscuro y la misma transparencia, donde antes eran más azules y opacas."

L["WN61_1_TITLE"] = "Preguntas de tamaño más claras"
L["WN61_1_TEXT"] = "Las preguntas y casillas sobre el tamaño de la interfaz nombran la escala de la interfaz del juego y el porcentaje que ponen, en menos palabras."
L["WN60_1_TITLE"] = "Marcos de jefe clásicos"
L["WN60_1_TEXT"] = "Los marcos de jefe de los combates de mazmorra y banda llevan el antiguo marco de dragón, con el nivel en su anillo redondo y la barra de lanzamiento al lado o debajo del marco. Para recuperar los del juego, desmarca Jefe en la lista Marcos de las opciones (/fcui), en Marcos de unidad."
L["WN60_2_TITLE"] = "Ocultar bordes de calidad"
L["WN60_2_TEXT"] = "Los objetos que llevas puestos en la ficha de personaje pueden mostrarse sin el borde de color de su calidad. Está desactivado por defecto; actívalo en las opciones (/fcui), en Ficha de personaje."
L["WN59_1_TITLE"] = "Menos trabajo para el juego"
L["WN59_1_TEXT"] = "Las placas de nombre trabajan mucho menos cuando cambias de objetivo, lanzas hechizos, ganas o pierdes auras, o estás entre otros jugadores. Los marcos de objetivo y de foco y la Lista Quién también hacen menos en segundo plano."
L["WN58_1_TITLE"] = "Marcadores de pueblos de Era"
L["WN58_1_TEXT"] = "Poblado Sañadiente y Fuerte Cenarion aparecen en los mapas de continente solo cuando has explorado su zona, como en Classic Era."
L["WN57_1_TITLE"] = "Mostrar bolsas con un clic"
L["WN57_1_TEXT"] = "Con Barra de bolsas: solo la mochila, un Ctrl-clic en la mochila muestra las demás bolsas o las vuelve a plegar; la flecha de al lado ya no está. Mostrar bolsas con elige otro clic. Para activarlo, elige Barra de bolsas: solo la mochila en las opciones (/fcui), en Bolsas."
L["WN57_2_TITLE"] = "Ocultar el arte del llavero"
L["WN57_2_TEXT"] = "Ocultar el arte del llavero ahora también despeja el hueco del llavero en la barra clásica y sustituye a Ocultar también el arte del llavero, conservando tu elección. Está desactivado por defecto; actívalo en las opciones (/fcui), en Bolsas."
L["WN57_3_TITLE"] = "Bolsas sin Barra clásica"
L["WN57_3_TEXT"] = "Con Barra clásica desactivada, las opciones que la barra de bolsas propia del juego no puede seguir aparecen en gris, y su descripción dice por qué."
L["WN56_1_TITLE"] = "Tema personalizado más rápido"
L["WN56_1_TEXT"] = "Cambiar de aspecto o una parte de Con tema ya no detiene el juego, y una parte desmarcada recupera los colores propios del juego. Tema personalizado está desactivado por defecto; actívalo en las opciones (/fcui), en Aspecto."
L["WN55_1_TITLE"] = "Textura de barra"
L["WN55_1_TEXT"] = "Una opción de Textura de barra en Marcos de unidad para las barras de salud y maná: Clásica, ahora más suave, Marcos de banda, Sólida o Barra de habilidad."
L["WN55_2_TITLE"] = "Botón de la tienda"
L["WN55_2_TEXT"] = "El botón de la tienda puede estar en el micromenú de la 1.x con un marco propio. Está oculto por defecto: para mostrarlo, desmarca Tienda en Ocultar microbotones, en la página Barras de acción de las opciones (/fcui)."
L["WN55_3_TITLE"] = "Botón del libro de hechizos"
L["WN55_3_TEXT"] = "El botón del libro de hechizos del micromenú se queda pulsado mientras el libro muestra tus hechizos."
L["WN55_4_TITLE"] = "Correcciones"
L["WN55_4_TEXT"] = "El consejo del botón social dice Social, y un título de ventana largo conserva los extremos de su placa de título."
L["WN54_1_TITLE"] = "Opciones más fluidas"
L["WN54_1_TEXT"] = "Cambiar una opción ya no da tirones: solo se vuelven a colocar las partes de la interfaz a las que afecta esa opción."
L["WN54_2_TITLE"] = "Micromenú"
L["WN54_2_TEXT"] = "Los microbotones que ocultas siguen ocultos, un botón que queda solo en la fila se coloca al final, y la fila queda centrada en la barra sin huecos en su suelo."
L["WN54_3_TITLE"] = "Minimapa en instancias"
L["WN54_3_TEXT"] = "Con Rotar minimapa activado, las instancias ya no muestran un segundo anillo grande alrededor del minimapa."
L["WN54_4_TITLE"] = "Botón de vivienda"
L["WN54_4_TEXT"] = "El botón de vivienda del micromenú tiene un marco 1.x como los demás."
L["WN54_5_TITLE"] = "Correcciones"
L["WN54_5_TEXT"] = "Tras recargar en combate, el marco propio del juego de la barra de experiencia ya no aparece sobre la barra 1.x, y un tamaño de ventana guardado en el modo edición ya no puede sacar una ventana de la pantalla, como un mapa del mundo grande."
L["WN53_1_TITLE"] = "Partes del tema más finas"
L["WN53_1_TEXT"] = "En Tema personalizado, la lista Con tema se divide en partes más finas, como las barras de lanzamiento, las placas de nombre, el micromenú y los menús, para que puedas dejar cualquiera con el aspecto clásico. Tema personalizado está desactivado por defecto; actívalo en las opciones (/fcui), en Aspecto."
L["WN53_2_TITLE"] = "Barras de acción derechas"
L["WN53_2_TEXT"] = "Con Barra clásica desactivada y el minimapa agrandado en el modo edición, las barras de acción 4 y 5 de la derecha ya no se reducen a unos dos tercios; solo se reducen lo que pide el espacio bajo el minimapa."
L["WN53_3_TITLE"] = "Color personalizado"
L["WN53_3_TEXT"] = "Hacer clic fuera del selector de color conserva el color elegido; Cancelar o Escape aún lo deshacen."
L["WN53_4_TITLE"] = "Arreglos del tema"
L["WN53_4_TEXT"] = "Cuando el tema colorea las ventanas del juego, ya no destellan con sus propios colores al abrirse, y los botones rojos del menú del juego muestran bien sus extremos. Los marcos de otros addons conservan su propio aspecto; para colorearlos también, activa Otros addons en la lista Con tema, en las opciones (/fcui), en Aspecto."
L["WN52_1_TITLE"] = "Insignia de honor"
L["WN52_1_TEXT"] = "Los marcos del jugador, del objetivo y de foco pueden mostrar la insignia de nivel de honor del juego en lugar del emblema de facción de la 1.x. Desactivado por defecto; actívalo en las opciones (/fcui), en Marcos de unidad."
L["WN52_2_TITLE"] = "Pestañas del chat al pasar el ratón"
L["WN52_2_TEXT"] = "Con las pestañas del chat al pasar el ratón, solo se muestran las pestañas de la ventana de chat bajo el ratón: las de las ventanas acopladas juntas, o la de una ventana que sacaste por separado."
L["WN52_3_TITLE"] = "Ojo del buscador de grupos"
L["WN52_3_TEXT"] = "Ajustar al minimapa del ojo del buscador de grupos ya no está en las opciones; sigue en los ajustes del ojo en el modo edición."
L["WN52_4_TITLE"] = "Ojo del buscador de grupos"
L["WN52_4_TEXT"] = "Ajustar al minimapa del ojo del buscador de grupos pasó de las opciones a su cuadro Buscador de grupos en Ventanas de ClassicUI Forever (modo edición), en Minimapa. El cuadro sigue ahí mientras el ojo está fuera del borde, para que puedas volver a activarlo."
L["WN52_5_TITLE"] = "Ayuda de Destello de daño"
L["WN52_5_TEXT"] = "La ayuda de Destello de daño dice que el rojo aparece en la barra de salud del marco del jugador. Destello de daño está desactivado por defecto; actívalo en las opciones (/fcui), en Marcos de unidad."
L["WN51_1_TITLE"] = "Maestría y versatilidad"
L["WN51_1_TEXT"] = "Las estadísticas de la ventana de personaje muestran Maestría y Versatilidad, en General."
L["WN51_2_TITLE"] = "Ventana de profesiones"
L["WN51_2_TEXT"] = "La elección de expansión está ahora en el menú Filtro. La ventana se abre donde están las demás ventanas del juego, sin hueco tras el libro de hechizos, y su borde inferior pasa bajo los botones Crear."
L["WN51_3_TITLE"] = "Opciones de Una bolsa"
L["WN51_3_TEXT"] = "Las opciones bajo Una bolsa solo cambian las ventanas de bolsa del addon, así que se ven en gris mientras Ventanas de bolsa está desactivado. Para usarlas, actívalo en las opciones (/fcui), en Bolsas."
L["WN51_4_TITLE"] = "Pestañas"
L["WN51_4_TEXT"] = "En las ventanas de profesiones y de talentos, la pestaña elegida muestra su cara entera y las demás pestañas ya no muestran una franja negra."
L["WN50_1_TITLE"] = "Color con textura"
L["WN50_1_TEXT"] = "Color con textura, que mantiene la textura del arte en el color del tema, ahora colorea ventanas enteras, no solo su metal: la piedra de bolsas y pestañas, los bordes de las cajas de búsqueda y de texto, y las flechas de página del libro de hechizos, donde una flecha usable es más clara que una agotada. Desactivado por defecto; actívalo en las opciones (/fcui), en Aspecto."
L["WN50_2_TITLE"] = "Temas en las ventanas del juego"
L["WN50_2_TEXT"] = "Los temas también colorean el arte propio del juego que queda en las ventanas que el addon rediseña: las pestañas de la ventana social, las barras de desplazamiento, las cajas de búsqueda, los desplegables como el de estado, la caja de dinero, las cabeceras de columna de la lista de hermandad, la caja de chat de las comunidades y la pestaña de banda."
L["WN50_3_TITLE"] = "Bronce en retail"
L["WN50_3_TEXT"] = "El tema Bronce ahora también colorea el arte propio de las ventanas del juego, que es plateado en retail, como hacen los demás temas."
L["WN50_4_TITLE"] = "Ocultar botones de ayuda"
L["WN50_4_TEXT"] = "Oculta los botones de ayuda del juego, la i arriba a la izquierda de ventanas como el mapa, las profesiones y el libro de hechizos, y los consejos de tutorial que abren. Activado por defecto; desactívalo en las opciones (/fcui), en Otros."
L["WN50_5_TITLE"] = "Ocultar pestaña lateral Quién"
L["WN50_5_TEXT"] = "El buscador de grupos puede quitar su pestaña lateral Quién, así Quién solo se abre desde la ventana social. Activado en instalaciones nuevas; si ya usabas el addon, actívalo en las opciones (/fcui), en Social."
L["WN50_6_TITLE"] = "Correcciones"
L["WN50_6_TEXT"] = "El anillo del retrato del libro de hechizos toma el tema Bronce en vez de quedarse plateado, y una flecha de página que puede volver a pasar ya no conserva su color agotado hasta que haces clic en otro sitio. Las placas de nombre muestran la calavera para unidades amistosas de nivel desconocido, como el marco de objetivo. El borde interior de las pestañas Amigos y Banda de la ventana social toma el color del tema, y se corrigió un error que el tema podía causar en combate."
